from collections import deque
import itertools

def best_final(a, max_ops):
    # BFS starting from a, depth <= max_ops
    n = len(a)
    seen = {tuple(a)}
    best = tuple(a)
    q = deque([(tuple(a),0)])
    while q:
        state, d = q.popleft()
        # update best
        if state < best:
            best = state
        if d == max_ops:
            continue
        for i in range(len(state)):
            new = list(state[:i] + state[i+1:]) + [state[i]+1]
            new_t = tuple(new)
            if new_t not in seen:
                seen.add(new_t)
                q.append((new_t, d+1))
    return best

