def best_with_path(a, max_ops):
    from collections import deque
    seen = {tuple(a):None}
    q = deque([(tuple(a),0)])
    parent = {}
    op_chosen = {}
    final_best = tuple(a)
    best_state = tuple(a)
    while q:
        state, d = q.popleft()
        if state < best_state:
            best_state = state
        if d == max_ops:
            continue
        for i in range(len(state)):
            new = state[:i] + state[i+1:] + (state[i]+1,)
            if new not in seen:
                seen[new] = (state, i)
                q.append((new, d+1))
    # reconstruct path to best_state
    cur = best_state
    path = []
    while seen[cur] is not None:
        prev, i = seen[cur]
        path.append(i)
        cur = prev
    path = list(reversed(path))
    return best_state, path
